#include <iostream>
#include <string>
#include <sstream>
#include <regex>

std::string markdown_to_html(const std::string& markdown) {
    std::stringstream ss;

    // Titres (h1 à h6)
    std::regex title_regex("^#{1,6}\\s+(.+?)\\s+#$");
    std::smatch title_match;
    if (std::regex_search(markdown, title_match, title_regex)) {
        std::string title = title_match[1];
        std::string html_title = "<h" + std::to_string(title_match.size() - 1) + ">" + title + "</h" + std::to_string(title_match.size() - 1) + ">";
        ss << html_title << std::endl;
        markdown.erase(0, title_match.position() + title_match.length());
    }

    // Gras
    std::regex bold_regex("\\*([^*]*)\\*");
    std::smatch bold_match;
    while (std::regex_search(markdown, bold_match, bold_regex)) {
        std::string bold_text = bold_match[1];
        std::string html_bold = "<strong>" + bold_text + "</strong>";
        ss << html_bold << std::endl;
        markdown.erase(bold_match.position(), bold_match.position() + bold_match.length());
    }

    // Italique
    std::regex italic_regex("_(.+?)_");
    std::smatch italic_match;
    while (std::regex_search(markdown, italic_match, italic_regex)) {
        std::string italic_text = italic_match[1];
        std::string html_italic = "<em>" + italic_text + "</em>";
        ss << html_italic << std::endl;
        markdown.erase(italic_match.position(), italic_match.position() + italic_match.length());
    }

    // Lien
    std::regex link_regex("\\[(.+?)\\]\\((.+?)\\)");
    std::smatch link_match;
    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string link_text = link_match[1];
        std::string link_url = link_match[2];
        std::string html_link = "<a href=\"" + link_url + "\" target=\"_blank\">" + link_text + "</a>";
        ss << html_link << std::endl;
        markdown.erase(link_match.position(), link_match.position() + link_match.length());
    }

    // Bloc de code
    std::regex code_block_regex("```(.*?)```");
    std::smatch code_block_match;
    if (std::regex_search(markdown, code_block_match, code_block_regex)) {
        std::string language = code_block_match[1];
        std::string html_code_block = "<pre><code class=\"" + language + "\">" + code_block_match[0] + "</code></pre>";
        ss << html_code_block << std::endl;
        markdown.erase(0, code_block_match.position() + code_block_match.length());
    }

    // Retourner le contenu HTML
    ss << markdown;
    return ss.str();
}

int main() {
    std::string markdown = "## Titre H2\n*Gras*\n_Italique_\n[lien](https://example.com)\n```C++\n#include <iostream>\nint main() {}\n```";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
